"""Original adult resuscitation questions, aligned to explicitly named 2025 guidance."""
from qbank_authoring import question,ref
rows=[]
BL=ref('AHA adult basic life support guideline: 2025','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support')
AL=ref('AHA adult advanced life support guideline: 2025','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support/')
PO=ref('AHA adult post-cardiac-arrest care guideline: 2025','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/post-cardiac-arrest-care')
ER=ref('ERC/ESICM post-resuscitation care guideline: 2025','https://doi.org/10.1016/j.resuscitation.2025.110809')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('An unresponsive adult has only occasional gasping and no definite pulse within a brief healthcare-provider assessment. What is appropriate?', 'Treat as cardiac arrest and begin CPR with rapid AED/defibrillator access',[
 ('Interpret gasping as adequate normal breathing','Agonal gasps are not effective ventilation.'),('Continue pulse checks for several minutes before acting','Prolonged assessment delays perfusion support.'),('Place the patient in a recovery position without resuscitation','This is inappropriate when arrest is suspected.')],
 'Gasping can accompany cardiac arrest','**Early recognition and compressions reduce no-flow time.**',['Assess rapidly and avoid an extended uncertain pulse check.','Activate emergency response and obtain a defibrillator.'],'**Provide high-quality CPR with ventilation according to training and equipment.**',['Reassess rhythm at appropriate intervals with minimal pauses.','Use team roles to reduce delays.'],[['Gasping','Not normal breathing'],['Pulse uncertainty','Do not prolong assessment'],['Action','CPR and defibrillator']],[BL],style='clinical_scenario')

q('Which compression rate is recommended for adult CPR?', '100–120 per minute',[
 ('60–80 per minute','This is too slow for standard adult CPR.'),('140–160 per minute','Excess speed can reduce depth and recoil.'),('180–200 per minute','This is not a recommended adult compression rate.')],
 'Rate, depth and recoil work together','**A rate within one hundred to one hundred twenty supports consistent high-quality compressions.**',['Avoid leaning and allow complete recoil.','Minimize interruptions and rotate compressors before fatigue degrades quality.'],'**Use feedback and the full quality bundle.**',['Do not achieve the rate by sacrificing depth.','Coordinate breaths without excessive interruption.'],[['Rate','100–120/min'],['Recoil','Complete'],['Pauses','Minimize']],[BL])

q('Which adult chest-compression depth is appropriate for an average-sized adult?', 'At least 5 cm while avoiding excessive depth greater than 6 cm',[
 ('About 2 cm','This is generally too shallow.'),('A minimum of 8 cm for every adult','Excessive depth increases injury risk and is not recommended.'),('Any depth is acceptable if the rate is correct','Depth is an independent component of CPR quality.')],
 'Adequate displacement supports forward flow','**Adult compressions should be deep enough for perfusion without unnecessary excessive depth.**',['Patient size and chest characteristics vary.','Use appropriate hand position and a firm surface.'],'**Check performance with feedback when available.**',['Maintain recoil and correct rate.','Recognize fatigue and change the compressor efficiently.'],[['Depth','5–6 cm practical range'],['Too shallow','Poor flow'],['Too deep','Excess injury risk']],[BL])

q('An adult in witnessed VF arrest has a defibrillator immediately available. Which action has priority?', 'Prompt unsynchronized defibrillation with minimal interruption of CPR',[
 ('Wait for central venous access before the first shock','Access must not delay defibrillation.'),('Give several antiarrhythmic doses before shocking','Early shock is the key rhythm-specific treatment.'),('Use synchronized cardioversion because VF is a tachyarrhythmia','VF has no organized complexes suitable for reliable synchronization.')],
 'A shockable arrest requires a shock','**Defibrillation can terminate the disorganized ventricular rhythm.**',['Prepare during compressions whenever safe.','Clear the patient for shock and resume CPR promptly.'],'**Follow the arrest algorithm and treat reversible causes.**',['Use the device-recommended energy and escalation protocol.','Do not pause repeatedly for unnecessary pulse checks.'],[['VF/pulseless VT','Unsynchronized shock'],['Access/drugs','Do not delay initial shock'],['After shock','Resume compressions']],[AL],style='clinical_scenario')

q('An organized narrow-complex rhythm is seen during resuscitation, but no pulse is present. Which rhythm category applies?', 'Pulseless electrical activity',[
 ('VF','VF is disorganized rather than an organized electrical rhythm.'),('Perfusing supraventricular tachycardia','Electrical organization does not guarantee mechanical output.'),('Asystole','Asystole lacks the described organized activity.')],
 'Electrical activity is not equivalent to circulation','**PEA is a nonshockable arrest category.**',['Continue high-quality CPR and give epinephrine promptly.','Identify causes such as hypoxia, hypovolemia, tamponade, tension pneumothorax or thrombosis.'],'**Treat the cause rather than shocking an organized rhythm without an indication.**',['Use focused bedside assessment without prolonging pauses.','Ultrasound can help selected diagnoses but must not interrupt core resuscitation.'],[['ECG','Organized activity'],['Pulse','Absent'],['Treatment','CPR/epinephrine/cause correction']],[AL],style='clinical_scenario')

q('According to AHA 2025 guidance, when should epinephrine be given in adult nonshockable cardiac arrest?', 'As soon as feasible during ongoing resuscitation',[
 ('Only after three defibrillation attempts','PEA and asystole are not treated with routine shocks.'),('Only after a central line is placed','A suitable available route should be used without that delay.'),('Only after the first twenty minutes of CPR','This unnecessarily delays indicated treatment.')],
 'Drug timing depends on rhythm category','**Early epinephrine is recommended for nonshockable arrest.**',['In shockable arrest, initial defibrillation attempts take priority.','Standard adult dosing intervals should follow the adopted algorithm.'],'**Give medication without compromising compressions or cause treatment.**',['Use IV access first when rapidly feasible and IO when needed.','Record administration times to avoid chaotic repeat dosing.'],[['Nonshockable','Early epinephrine'],['Shockable','Initial shocks first'],['All rhythms','High-quality CPR']],[AL])

q('After placement of an advanced airway during adult CPR, which ventilation strategy is appropriate?', 'Continuous compressions with approximately one breath every 6 seconds',[
 ('Pause compressions for every breath indefinitely','An advanced airway permits asynchronous ventilation.'),('Give 30–40 breaths per minute to maximize oxygen delivery','Excessive ventilation raises intrathoracic pressure and can impair venous return.'),('Stop ventilation because compressions alone eliminate CO2 adequately','Effective gas exchange remains necessary.')],
 'Avoid hyperventilation during resuscitation','**A typical advanced-airway adult rate is ten breaths per minute.**',['Deliver enough volume for visible chest rise without excessive pressure.','Confirm the airway and monitor waveform capnography.'],'**Coordinate the team to preserve compression quality.**',['Reassess position after movement or sudden deterioration.','Treat obstruction, leaks and equipment problems promptly.'],[['Compressions','Continuous'],['Breaths','About 10/min'],['Excess ventilation','Can reduce venous return']],[AL])

q('What is the preferred method for confirming and continuously monitoring an endotracheal tube during resuscitation when available?', 'Continuous waveform capnography with clinical assessment',[
 ('Auscultation alone as an infallible test','Breath sounds can be misleading.'),('Condensation in the tube as definitive confirmation','Condensation does not reliably exclude esophageal placement.'),('Pulse oximetry alone immediately after insertion','Saturation may remain temporarily normal despite misplacement.')],
 'Use a direct repeated ventilation signal','**A sustained appropriate capnographic waveform supports tracheal placement.**',['Very low pulmonary blood flow can reduce the signal during arrest.','Interpret device function and the complete clinical context.'],'**Continue monitoring throughout resuscitation and transport.**',['A sudden loss can indicate displacement, obstruction, circuit failure or major perfusion change.','Do not use one isolated number as a complete airway assessment.'],[['Placement','Waveform plus clinical checks'],['Monitoring','Continuous'],['Signal loss','Immediate reassessment']],[AL])

q('During CPR, end-tidal CO2 abruptly rises and remains higher without a ventilation change. What should be considered?', 'Return of spontaneous circulation',[
 ('Definite esophageal intubation as the only explanation','Sustained increased CO2 can reflect improved pulmonary blood flow.'),('A mandatory indication to stop CPR without checking circulation','The clue requires an appropriate rhythm/pulse assessment.'),('Proof that chest compressions are causing a fatal CO2 rise','ETCO2 reflects both ventilation and perfusion, not simply harmful accumulation.')],
 'Perfusion changes the amount of CO2 delivered to the lungs','**A sudden sustained ETCO2 increase can signal ROSC.**',['Ventilator changes and administered drugs can also affect readings.','Avoid unnecessary pauses for every minor fluctuation.'],'**Confirm circulation at an appropriate brief assessment.**',['Then transition to structured post-arrest care.','Continue monitoring for rearrest and the original cause.'],[['ETCO2 rise','Possible increased blood flow'],['Confirmation','Brief circulation assessment'],['Next phase','Post-arrest stabilization']],[AL],style='clinical_scenario')

q('Why should point-of-care ultrasound during cardiac arrest be tightly coordinated with planned brief pauses?', 'It can help identify reversible causes but prolonged pauses reduce coronary and cerebral perfusion',[
 ('Any diagnostic image is more important than compression continuity','Imaging benefit does not justify avoidable no-flow time.'),('Cardiac standstill on a single view independently proves futility','A single ultrasound finding is not a universal termination rule.'),('Ultrasound replaces rhythm analysis and clinical assessment','It is an adjunct rather than a complete replacement.')],
 'A useful test can harm if it delays treatment','**The core resuscitation process must remain uninterrupted as much as possible.**',['Prepare the probe before a planned pause.','Acquire and interpret images efficiently without extending the pause.'],'**Use findings to guide a plausible cause-directed intervention.**',['Avoid overinterpreting nonspecific right-heart changes during arrest.','Continue appropriate CPR and standard algorithm care.'],[['Potential benefit','Reversible-cause clues'],['Risk','Longer interruptions'],['Use','Coordinated experienced team']],[AL])

q('Which statement about routine calcium administration in undifferentiated adult cardiac arrest is correct?', 'It is not routinely recommended; use specific indications such as selected electrolyte or toxicological causes',[
 ('It should be given to every patient after the first CPR cycle','Routine administration has no established universal benefit.'),('It replaces epinephrine in all nonshockable arrest','It is not a general substitute.'),('It is prohibited even in all calcium-channel-blocker poisoning','Specific poisoning/electrolyte contexts differ from undifferentiated arrest.')],
 'Distinguish a specific antidotal indication from routine arrest treatment','**More resuscitation drugs do not automatically improve outcomes.**',['Cause-specific therapy may be appropriate.','The evidence and recommendation vary with the suspected mechanism.'],'**Follow the relevant special-circumstance algorithm.**',['Do not delay CPR or defibrillation to administer an unindicated drug.','Use available history, ECG and rapid laboratory information appropriately.'],[['Undifferentiated arrest','No routine calcium'],['Specific cause','Selected indications'],['Core care','CPR/defibrillation/algorithm']],[AL])

q('What is the appropriate role of extracorporeal CPR for refractory adult cardiac arrest?', 'A selected rescue strategy in systems able to provide rapid deployment and definitive treatment of a reversible cause',[
 ('Routine treatment for every arrest irrespective of cause or downtime','Candidacy and system capability are essential.'),('A reason to delay conventional CPR while transfer is discussed','Conventional resuscitation must continue.'),('A guaranteed neurologically intact recovery once flow is established','Extracorporeal circulation does not reverse all prior ischemic injury.')],
 'ECPR is a time- and system-dependent pathway','**Selected patients may benefit when a reversible problem can be treated.**',['No-flow/low-flow duration, comorbidity and cause affect selection.','Team readiness and transport logistics influence feasibility.'],'**Use predefined criteria and continue high-quality resuscitation.**',['Plan definitive coronary, pulmonary or toxicological treatment where appropriate.','Reassess proportionality as clinical information evolves.'],[['Selection','Reversibility and patient factors'],['System','Rapid expert deployment'],['Bridge','Definitive cause treatment']],[AL])
